import { useCallback, useState, type KeyboardEvent } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
  locale?: string;
};

const DAY_MS = 24 * 60 * 60 * 1000;

const PRESETS = [
  { id: 'today', label: 'Сегодня', days: 0 },
  { id: 'yesterday', label: 'Вчера', days: 1 },
  { id: 'week', label: 'Неделя назад', days: 7 },
];

function startOfDay(date: Date): Date {
  const next = new Date(date);
  next.setHours(0, 0, 0, 0);
  return next;
}

function daysAgo(days: number): Date {
  return startOfDay(new Date(Date.now() - days * DAY_MS));
}

function isSameDay(a: Date | null, b: Date): boolean {
  return a != null && startOfDay(a).getTime() === b.getTime();
}

export default function ReportDatePicker({
  value,
  defaultValue = null,
  onChange,
  locale = 'ru-RU',
}: ReportDatePickerProps) {
  const [inner, setInner] = useState<Date | null>(defaultValue);
  const selected = value !== undefined ? value : inner;

  const commit = useCallback(
    (next: Date | null) => {
      if (value === undefined) setInner(next);
      onChange?.(next);
    },
    [onChange, value],
  );

  const handlePresetKeyDown = (event: KeyboardEvent<HTMLSpanElement>, next: Date) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      commit(next);
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <span
          id="report-date-presets-label"
          style={{
            font: 'inherit',
            fontFamily: 'var(--jx-font-sans)',
            fontSize: '13px',
            color: 'var(--jx-text-2)',
          }}
        >
          Дата отчёта
        </span>
        <div
          role="group"
          aria-labelledby="report-date-presets-label"
          style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
        >
          {PRESETS.map((preset) => {
            const presetDate = daysAgo(preset.days);
            const active = isSameDay(selected, presetDate);
            return (
              <JxChip
                key={preset.id}
                role="button"
                tabIndex={0}
                aria-pressed={active}
                active={active}
                onClick={() => commit(presetDate)}
                onKeyDown={(event) => handlePresetKeyDown(event, presetDate)}
              >
                {preset.label}
              </JxChip>
            );
          })}
        </div>
      </div>

      <JxCalendar locale={locale} value={selected} onValueChange={commit} />

      <span
        aria-live="polite"
        style={{
          fontFamily: 'var(--jx-font-sans)',
          fontSize: '13px',
          color: selected ? 'var(--jx-text)' : 'var(--jx-text-2)',
        }}
      >
        {selected
          ? `Выбрано: ${selected.toLocaleDateString(locale, {
              day: 'numeric',
              month: 'long',
              year: 'numeric',
            })}`
          : 'Дата не выбрана — выберите день в календаре или быстрый вариант выше'}
      </span>
    </div>
  );
}

